#include <stdio.h>
#include <stdlib.h>

// ----------------------------
// STRUCTURE OF A NODE
// ----------------------------
struct Node {
    int data;                  // stores data value
    struct Node *left;         // pointer to left child
    struct Node *right;        // pointer to right child
};

// ----------------------------
// CREATE A NEW NODE
// ----------------------------
struct Node* createNode(int value) {
    struct Node* newNode;

    newNode = (struct Node*)malloc(sizeof(struct Node)); // allocate memory

    newNode->data = value;       // store value in data
    newNode->left = NULL;        // initially no left child
    newNode->right = NULL;       // initially no right child

    return newNode;              // return newly created node
}

// ----------------------------
// INSERT A NODE IN BST
// ----------------------------
struct Node* insert(struct Node* root, int value) {

    // if tree is empty, new node becomes root
    if (root == NULL) {
        root = createNode(value);
        return root;
    }

    // if value is smaller, go to left side
    if (value < root->data) {
        root->left = insert(root->left, value);
    }
    // if value is greater, go to right side
    else if (value > root->data) {
        root->right = insert(root->right, value);
    }
    // if value is equal, ignore (no duplicates)
    else {
        printf("Duplicate value not allowed!\n");
    }

    return root;  // return unchanged root
}

// ----------------------------
// SEARCH A NODE IN BST
// ----------------------------
struct Node* search(struct Node* root, int key) {

    // if tree empty or found node
    if (root == NULL || root->data == key) {
        return root;
    }

    // if key smaller, search in left
    if (key < root->data) {
        return search(root->left, key);
    }
    // if key greater, search in right
    else {
        return search(root->right, key);
    }
}

// ----------------------------
// INORDER TRAVERSAL (LEFT → ROOT → RIGHT)
// ----------------------------
void inorder(struct Node* root) {
    if (root != NULL) {
        inorder(root->left);
        printf("%d ", root->data);
        inorder(root->right);
    }
}

// ----------------------------
// PREORDER TRAVERSAL (ROOT → LEFT → RIGHT)
// ----------------------------
void preorder(struct Node* root) {
    if (root != NULL) {
        printf("%d ", root->data);
        preorder(root->left);
        preorder(root->right);
    }
}

// ----------------------------
// POSTORDER TRAVERSAL (LEFT → RIGHT → ROOT)
// ----------------------------
void postorder(struct Node* root) {
    if (root != NULL) {
        postorder(root->left);
        postorder(root->right);
        printf("%d ", root->data);
    }
}

// ----------------------------
// FIND MINIMUM VALUE NODE (used in delete)
// ----------------------------
struct Node* findMin(struct Node* root) {
    while (root->left != NULL) {
        root = root->left;
    }
    return root;
}

// ----------------------------
// DELETE A NODE FROM BST
// ----------------------------
struct Node* deleteNode(struct Node* root, int key) {

    // if tree empty
    if (root == NULL) {
        return root;
    }

    // if key smaller → go left
    if (key < root->data) {
        root->left = deleteNode(root->left, key);
    }
    // if key greater → go right
    else if (key > root->data) {
        root->right = deleteNode(root->right, key);
    }
    // if key == root->data → delete this node
    else {
        // Case 1: No child (leaf)
        if (root->left == NULL && root->right == NULL) {
            free(root);
            root = NULL;
        }
        // Case 2: One child (right)
        else if (root->left == NULL) {
            struct Node* temp;
            temp = root->right;
            free(root);
            root = temp;
        }
        // Case 3: One child (left)
        else if (root->right == NULL) {
            struct Node* temp;
            temp = root->left;
            free(root);
            root = temp;
        }
        // Case 4: Two children
        else {
            struct Node* temp;
            temp = findMin(root->right);  // find inorder successor
            root->data = temp->data;      // replace data
            root->right = deleteNode(root->right, temp->data); // delete successor
        }
    }

    return root;
}

// ----------------------------
// COUNT TOTAL NODES
// ----------------------------
int countNodes(struct Node* root) {
    if (root == NULL) {
        return 0;
    }
    else {
        int leftCount = countNodes(root->left);
        int rightCount = countNodes(root->right);
        return leftCount + rightCount + 1;
    }
}

// ----------------------------
// COUNT LEAF NODES
// ----------------------------
int countLeaves(struct Node* root) {
    if (root == NULL) {
        return 0;
    }
    if (root->left == NULL && root->right == NULL) {
        return 1;
    }
    else {
        int leftLeaf = countLeaves(root->left);
        int rightLeaf = countLeaves(root->right);
        return leftLeaf + rightLeaf;
    }
}

// ----------------------------
// HEIGHT OF TREE
// ----------------------------
int height(struct Node* root) {
    if (root == NULL) {
        return 0;
    }
    else {
        int leftH = height(root->left);
        int rightH = height(root->right);

        if (leftH > rightH)
            return leftH + 1;
        else
            return rightH + 1;
    }
}

// ----------------------------
// LEVEL ORDER (BFS)
// ----------------------------
void levelOrder(struct Node* root) {
    if (root == NULL) {
        printf("Tree is empty!\n");
        return;
    }

    struct Node* queue[100];
    int front = 0;
    int rear = 0;

    queue[rear] = root;
    rear++;

    while (front < rear) {
        struct Node* current = queue[front];
        front++;

        printf("%d ", current->data);

        if (current->left != NULL) {
            queue[rear] = current->left;
            rear++;
        }

        if (current->right != NULL) {
            queue[rear] = current->right;
            rear++;
        }
    }
}

// ----------------------------
